import gzip
rows=[]
for line in gzip.open('data/plasma.report.gz','rt'):
    f=line.rstrip('\n').split('\t')
    rank=f[3]; name=f[5].strip()
    if rank.startswith('S') or 'Homo' in name or 'Primates' in name or 'Eukaryota' in name:
        rows.append((int(f[1]),int(f[2]),rank,f[4],name,len(f[5])-len(f[5].lstrip(' '))))
for r in sorted(rows,reverse=True)[:70]: print(r)
"
